/**
 * RFC 7807 Problem Details for HTTP APIs
 * @see https://tools.ietf.org/html/rfc7807
 */
export interface ApiProblem {
  /** A URI reference that identifies the problem type */
  type: string;
  /** A short, human-readable summary of the problem */
  title: string;
  /** The HTTP status code generated by the origin server */
  status: number;
  /** A human-readable explanation specific to this occurrence of the problem */
  detail?: string;
  /** A URI reference that identifies the specific occurrence of the problem */
  instance?: string;
  /** Application-specific error code */
  code?: string;
  /** Additional error details array */
  errors?: Array<{
    field?: string;
    message: string;
    code?: string;
  }>;
}

/**
 * Standard problem type URIs
 */
export const ProblemTypes = {
  BAD_REQUEST: 'urn:anchorpoint:error:bad-request',
  UNAUTHORIZED: 'urn:anchorpoint:error:unauthorized',
  FORBIDDEN: 'urn:anchorpoint:error:forbidden',
  NOT_FOUND: 'urn:anchorpoint:error:not-found',
  CONFLICT: 'urn:anchorpoint:error:conflict',
  VALIDATION_ERROR: 'urn:anchorpoint:error:validation-error',
  RATE_LIMIT_EXCEEDED: 'urn:anchorpoint:error:rate-limit-exceeded',
  INTERNAL_SERVER_ERROR: 'urn:anchorpoint:error:internal-server-error',
  SERVICE_UNAVAILABLE: 'urn:anchorpoint:error:service-unavailable',
} as const;

/**
 * Application-specific error codes
 */
export enum ErrorCode {
  // Validation
  VALIDATION_ERROR = 'VALIDATION_ERROR',
  INVALID_PARAMETER = 'INVALID_PARAMETER',
  MISSING_REQUIRED_FIELD = 'MISSING_REQUIRED_FIELD',

  // Authentication & Authorization
  UNAUTHORIZED = 'UNAUTHORIZED',
  TOKEN_EXPIRED = 'TOKEN_EXPIRED',
  INVALID_TOKEN = 'INVALID_TOKEN',
  FORBIDDEN = 'FORBIDDEN',
  INSUFFICIENT_PERMISSIONS = 'INSUFFICIENT_PERMISSIONS',

  // Resource
  NOT_FOUND = 'NOT_FOUND',
  CONFLICT = 'CONFLICT',
  ALREADY_EXISTS = 'ALREADY_EXISTS',

  // Rate limiting
  RATE_LIMIT_EXCEEDED = 'RATE_LIMIT_EXCEEDED',

  // Business logic
  INSUFFICIENT_BALANCE = 'INSUFFICIENT_BALANCE',
  INVALID_AMOUNT = 'INVALID_AMOUNT',
  TRANSACTION_FAILED = 'TRANSACTION_FAILED',

  // System
  INTERNAL_SERVER_ERROR = 'INTERNAL_SERVER_ERROR',
  SERVICE_UNAVAILABLE = 'SERVICE_UNAVAILABLE',
  EXTERNAL_SERVICE_ERROR = 'EXTERNAL_SERVICE_ERROR',
}

/**
 * Base class for typed application exceptions
 */
export abstract class AppException extends Error {
  public readonly statusCode: number;
  public readonly type: string;
  public readonly code: string;
  public readonly detail?: string;
  public readonly instance?: string;
  public readonly errors?: Array<{ field?: string; message: string; code?: string }>;
  public readonly isOperational: boolean;

  constructor(params: {
    message: string;
    statusCode: number;
    type: string;
    code: string;
    detail?: string;
    instance?: string;
    errors?: Array<{ field?: string; message: string; code?: string }>;
    isOperational?: boolean;
  }) {
    super(params.message);
    this.statusCode = params.statusCode;
    this.type = params.type;
    this.code = params.code;
    this.detail = params.detail;
    this.instance = params.instance;
    this.errors = params.errors;
    this.isOperational = params.isOperational ?? true;
    Error.captureStackTrace(this, this.constructor);
  }

  /**
   * Convert to RFC 7807 ApiProblem format
   */
  toProblem(): ApiProblem {
    return {
      type: this.type,
      title: this.code,
      status: this.statusCode,
      detail: this.detail ?? this.message,
      instance: this.instance,
      code: this.code,
      errors: this.errors,
    };
  }
}

/**
 * Validation error (400)
 */
export class ValidationError extends AppException {
  constructor(params: {
    message: string;
    errors?: Array<{ field?: string; message: string; code?: string }>;
    detail?: string;
  }) {
    super({
      message: params.message,
      statusCode: 400,
      type: ProblemTypes.VALIDATION_ERROR,
      code: ErrorCode.VALIDATION_ERROR,
      errors: params.errors,
      detail: params.detail,
    });
  }
}

/**
 * Bad request error (400)
 */
export class BadRequestError extends AppException {
  constructor(params: { message: string; detail?: string; code?: string }) {
    super({
      message: params.message,
      statusCode: 400,
      type: ProblemTypes.BAD_REQUEST,
      code: params.code ?? ErrorCode.BAD_REQUEST,
      detail: params.detail,
    });
  }
}

/**
 * Unauthorized error (401)
 */
export class UnauthorizedError extends AppException {
  constructor(params: { message: string; detail?: string }) {
    super({
      message: params.message,
      statusCode: 401,
      type: ProblemTypes.UNAUTHORIZED,
      code: ErrorCode.UNAUTHORIZED,
      detail: params.detail,
    });
  }
}

/**
 * Forbidden error (403)
 */
export class ForbiddenError extends AppException {
  constructor(params: { message: string; detail?: string }) {
    super({
      message: params.message,
      statusCode: 403,
      type: ProblemTypes.FORBIDDEN,
      code: ErrorCode.FORBIDDEN,
      detail: params.detail,
    });
  }
}

/**
 * Not found error (404)
 */
export class NotFoundError extends AppException {
  constructor(params: { message: string; resource?: string; id?: string; detail?: string }) {
    super({
      message: params.message,
      statusCode: 404,
      type: ProblemTypes.NOT_FOUND,
      code: ErrorCode.NOT_FOUND,
      detail: params.detail,
      instance: params.id ? `/api/v1/${params.resource}/${params.id}` : undefined,
    });
  }
}

/**
 * Conflict error (409)
 */
export class ConflictError extends AppException {
  constructor(params: { message: string; detail?: string }) {
    super({
      message: params.message,
      statusCode: 409,
      type: ProblemTypes.CONFLICT,
      code: ErrorCode.CONFLICT,
      detail: params.detail,
    });
  }
}

/**
 * Rate limit exceeded error (429)
 */
export class RateLimitError extends AppException {
  constructor(params: { message: string; detail?: string; retryAfter?: number }) {
    super({
      message: params.message,
      statusCode: 429,
      type: ProblemTypes.RATE_LIMIT_EXCEEDED,
      code: ErrorCode.RATE_LIMIT_EXCEEDED,
      detail: params.detail,
    });
  }
}

/**
 * Internal server error (500)
 */
export class InternalServerError extends AppException {
  constructor(params: { message: string; detail?: string; isOperational?: boolean }) {
    super({
      message: params.message,
      statusCode: 500,
      type: ProblemTypes.INTERNAL_SERVER_ERROR,
      code: ErrorCode.INTERNAL_SERVER_ERROR,
      detail: params.detail,
      isOperational: params.isOperational ?? false,
    });
  }
}

/**
 * Service unavailable error (503)
 */
export class ServiceUnavailableError extends AppException {
  constructor(params: { message: string; detail?: string }) {
    super({
      message: params.message,
      statusCode: 503,
      type: ProblemTypes.SERVICE_UNAVAILABLE,
      code: ErrorCode.SERVICE_UNAVAILABLE,
      detail: params.detail,
    });
  }
}